n = int(input())
words = input().split()
groups = {}
for w in words:
    key = "".join(sorted(w))
    groups.setdefault(key, []).append(w)

lines = []
for members in groups.values():
    if len(members) >= 2:
        lines.append(sorted(members))
lines.sort()

if not lines:
    print("없음")
for members in lines:
    print(" ".join(members))
